def make_variants(apps, schema_editor):
    """Products that already had options get one variant per combination; their stock is split evenly
    (the remainder to the first ones), so each product's total stays what it was."""
    Product, Variant = apps.get_model("shop", "Product"), apps.get_model("shop", "ProductVariant")
    for p in Product.objects.filter(options__isnull=False).distinct():
        options = list(p.options.order_by("position", "id"))
        choices = [list(dict.fromkeys(v.strip() for v in o.values.split(",") if v.strip())) for o in options]
        keys = [urlencode(sorted(zip([o.name for o in options], combo))) for combo in itertools.product(*choices)]
        if keys:
            each, extra = divmod(p.stock, len(keys))
            Variant.objects.bulk_create(Variant(product=p, key=k, stock=each + (i < extra)) for i, k in enumerate(keys))


